const config = {
  "previewFeatures": [
    "postgresqlExtensions"
  ],
  "clientVersion": "7.5.0",
  "engineVersion": "280c870be64f457428992c43c1f6d557fab6e29e",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider        = \"prisma-client-js\"\n  output          = \"../src/lib/generated/prisma\"\n  previewFeatures = [\"postgresqlExtensions\"]\n  binaryTargets   = [\"native\", \"rhel-openssl-3.0.x\", \"debian-openssl-3.0.x\"]\n}\n\ndatasource db {\n  provider   = \"postgresql\"\n  extensions = [citext]\n}\n\nmodel ChainState {\n  id              String @id @default(cuid())\n  userAddress     String @db.Citext\n  contract        String @db.Citext\n  lastBlockNumber Int    @default(0)\n\n  @@unique([userAddress, contract], name: \"contract_userAddress\")\n}\n\nmodel User {\n  id                 String                 @id @default(cuid())\n  walletAddress      String                 @unique @db.Citext\n  username           String\n  bio                String?\n  profileBanner      String?\n  profileAvatar      String\n  x                  String?\n  instagram          String?\n  website            String?\n  telegram           String?\n  createdAt          DateTime               @default(now())\n  updatedAt          DateTime               @updatedAt\n  collections        Collection[]\n  submissions        CollectionSubmission[]\n  holderRewardsMulti HolderRewardMulti[]\n  ownedNFTs          NFT[]                  @relation(\"ownedNFTs\")\n  rewardClaimLogs    RewardClaimLog[]\n  stolenReports      StolenItem[]           @relation(\"StolenReporter\")\n\n  // Warpool\n  warpoolEntries         WarpoolEntry[]\n  warpoolReservations    WarpoolReservation[]\n  warpoolActivities      WarpoolActivity[]\n  warpoolCapturesAsOwner WarpoolCapture[]     @relation(\"WarpoolCaptureOriginalOwner\")\n\n  // Admin proposals\n  adminProposalsCreated AdminProposal[]      @relation(\"AdminProposalCreatedByUser\")\n  adminProposalsEdited  AdminProposal[]      @relation(\"AdminProposalLastEditedByUser\")\n  adminProposalEvents   AdminProposalEvent[] @relation(\"AdminProposalEventActorUser\")\n}\n\nmodel Collection {\n  id           String            @id @default(cuid())\n  name         String\n  symbol       String\n  contract     String            @unique @db.Citext\n  description  String?\n  logoUrl      String?\n  coverUrl     String?\n  standard     String            @default(\"ERC721\")\n  supply       Int?\n  baseUri      String?\n  gatewayPref  GatewayPref       @default(PUBLIC)\n  indexStatus  IndexStatus       @default(PENDING)\n  x            String?\n  instagram    String?\n  website      String?\n  discord      String?\n  telegram     String?\n  floorPrice   Float             @default(0)\n  volume       Float             @default(0)\n  itemsCount   Int               @default(0)\n  ownersCount  Int               @default(0)\n  change24h    Float             @default(0)\n  creatorId    String\n  ownerAddress String            @db.Citext\n  isOrphan     Boolean           @default(false)\n  createdAt    DateTime          @default(now())\n  updatedAt    DateTime          @updatedAt\n  assetUploads AssetUpload[]\n  creator      User              @relation(fields: [creatorId], references: [id])\n  deployment   DeployedContract?\n  nfts         NFT[]\n  presale      Presale?\n  publicSale   PublicSale?\n\n  @@index([creatorId])\n  @@index([ownerAddress])\n  @@index([indexStatus])\n}\n\nmodel NFT {\n  id               String               @id @default(cuid())\n  tokenId          String\n  name             String?\n  imageUrl         String?\n  description      String?\n  traits           Json?\n  attributes       Json?\n  tokenUri         String?\n  contract         String               @db.Citext\n  standard         String?\n  rawMetadata      Json?\n  royaltyBps       Int?\n  royaltyRecipient String?              @db.Citext\n  ownerId          String?\n  collectionId     String?\n  single721Id      String?\n  single1155Id     String?\n  status           NftStatus            @default(PENDING)\n  retryCount       Int                  @default(0)\n  createdAt        DateTime             @default(now())\n  updatedAt        DateTime             @updatedAt\n  rarityScore      Decimal?             @db.Decimal(38, 18)\n  auctionEntries   Auction[]\n  listingEntries   MarketplaceListing[]\n  sales            MarketplaceSale[]\n  collection       Collection?          @relation(fields: [collectionId], references: [id])\n  owner            User?                @relation(\"ownedNFTs\", fields: [ownerId], references: [id])\n  single1155       Single1155?          @relation(fields: [single1155Id], references: [id])\n  single721        Single721?           @relation(fields: [single721Id], references: [id])\n  activities       NFTActivity[]\n\n  // Warpool\n  warpoolEntries      WarpoolEntry[]\n  warpoolReservations WarpoolReservation[]\n  warpoolActivities   WarpoolActivity[]\n  warpoolCaptures     WarpoolCapture[]\n\n  @@unique([contract, tokenId])\n  @@unique([tokenId, contract, collectionId])\n  @@index([contract])\n  @@index([ownerId])\n}\n\nmodel TraitStat {\n  id         String   @id @default(cuid())\n  contract   String   @db.Citext\n  trait_type String\n  value      Json\n  count      Int\n  frequency  Float\n  createdAt  DateTime @default(now())\n\n  @@unique([contract, trait_type, value])\n  @@index([contract])\n}\n\nmodel NFTActivity {\n  id          String   @id @default(cuid())\n  nftId       String\n  contract    String   @db.Citext\n  tokenId     String\n  type        String\n  fromAddress String   @db.Citext\n  toAddress   String   @db.Citext\n  priceEtnWei Decimal? @db.Decimal(65, 0)\n  txHash      String\n  logIndex    Int      @default(0)\n  blockNumber Int\n  timestamp   DateTime\n  marketplace String?\n  rawData     Json?\n  createdAt   DateTime @default(now())\n  nft         NFT      @relation(fields: [nftId], references: [id])\n\n  @@unique([txHash, logIndex])\n  @@index([contract])\n  @@index([tokenId])\n  @@index([timestamp])\n  @@index([contract, tokenId, blockNumber])\n}\n\nmodel Single721 {\n  id               String            @id @default(cuid())\n  name             String\n  symbol           String\n  contract         String            @unique @db.Citext\n  tokenUri         String\n  royaltyRecipient String            @db.Citext\n  royaltyBps       Int\n  creatorId        String\n  ownerAddress     String            @db.Citext\n  description      String?\n  imageUrl         String?\n  indexStatus      IndexStatus       @default(PENDING)\n  createdAt        DateTime          @default(now())\n  updatedAt        DateTime          @updatedAt\n  assetUploads     AssetUpload[]\n  deployment       DeployedContract?\n  nfts             NFT[]\n\n  @@index([indexStatus])\n}\n\nmodel Single1155 {\n  id               String            @id @default(cuid())\n  name             String\n  symbol           String\n  contract         String            @unique @db.Citext\n  baseUri          String\n  maxSupply        Int\n  mintPriceEtnWei  Decimal           @db.Decimal(65, 0)\n  maxPerWallet     Int\n  royaltyRecipient String            @db.Citext\n  royaltyBps       Int\n  creatorId        String\n  ownerAddress     String            @db.Citext\n  description      String?\n  imageUrl         String?\n  indexStatus      IndexStatus       @default(PENDING)\n  createdAt        DateTime          @default(now())\n  updatedAt        DateTime          @updatedAt\n  assetUploads     AssetUpload[]\n  deployment       DeployedContract?\n  balances         Erc1155Balance[]\n  nfts             NFT[]\n\n  @@index([indexStatus])\n}\n\nmodel Erc1155Balance {\n  id           String     @id @default(cuid())\n  single1155Id String\n  ownerAddress String     @db.Citext\n  balance      Int        @default(0)\n  updatedAt    DateTime   @default(now())\n  single1155   Single1155 @relation(fields: [single1155Id], references: [id])\n\n  @@unique([single1155Id, ownerAddress])\n  @@index([ownerAddress])\n  @@index([single1155Id])\n}\n\nmodel Erc1155Holding {\n  id           String   @id @default(cuid())\n  contract     String   @db.Citext\n  tokenId      String\n  ownerAddress String   @db.Citext\n  balance      Int      @default(0)\n  updatedAt    DateTime @default(now())\n\n  @@unique([contract, tokenId, ownerAddress])\n  @@index([ownerAddress])\n  @@index([contract, tokenId])\n  @@index([contract, ownerAddress])\n}\n\nmodel MarketplaceListing {\n  id               String        @id @default(cuid())\n  nftId            String\n  sellerAddress    String        @db.Citext\n  quantity         Int           @default(1)\n  priceEtnWei      Decimal       @db.Decimal(65, 0)\n  currencyId       String?\n  priceTokenAmount Decimal?      @db.Decimal(65, 0)\n  status           ListingStatus @default(ACTIVE)\n  startTime        DateTime      @default(now())\n  endTime          DateTime?\n  txHashCreated    String?\n  txHashFilled     String?\n  txHashCancelled  String?\n  createdAt        DateTime      @default(now())\n  updatedAt        DateTime      @updatedAt\n  currency         Currency?     @relation(fields: [currencyId], references: [id])\n  nft              NFT           @relation(fields: [nftId], references: [id])\n\n  // Warpool\n  relistCaptures WarpoolCapture[]\n\n  @@index([sellerAddress])\n  @@index([status])\n  @@index([startTime])\n  @@index([nftId])\n  @@index([currencyId])\n  @@index([nftId, status], map: \"idx_listing_nft_status\")\n  @@index([sellerAddress, status], map: \"idx_listing_seller_status\")\n}\n\nmodel Auction {\n  id                      String        @id @default(cuid())\n  nftId                   String\n  sellerAddress           String        @db.Citext\n  quantity                Int           @default(1)\n  startPriceEtnWei        Decimal       @db.Decimal(65, 0)\n  highestBidEtnWei        Decimal?      @db.Decimal(65, 0)\n  minIncrementEtnWei      Decimal?      @db.Decimal(65, 0)\n  currencyId              String?\n  startPriceTokenAmount   Decimal?      @db.Decimal(65, 0)\n  highestBidTokenAmount   Decimal?      @db.Decimal(65, 0)\n  minIncrementTokenAmount Decimal?      @db.Decimal(65, 0)\n  startTime               DateTime      @default(now())\n  endTime                 DateTime\n  status                  AuctionStatus @default(ACTIVE)\n  txHashCreated           String?\n  txHashFinalized         String?\n  txHashCancelled         String?\n  createdAt               DateTime      @default(now())\n  updatedAt               DateTime      @updatedAt\n  highestBidder           String?       @db.Citext\n  currency                Currency?     @relation(fields: [currencyId], references: [id])\n  nft                     NFT           @relation(fields: [nftId], references: [id])\n  bids                    AuctionBid[]\n\n  @@index([sellerAddress])\n  @@index([status])\n  @@index([endTime])\n  @@index([nftId])\n  @@index([currencyId])\n  @@index([nftId, status], map: \"idx_auction_nft_status\")\n  @@index([sellerAddress, status], map: \"idx_auction_seller_status\")\n}\n\nmodel AuctionBid {\n  id            String    @id @default(cuid())\n  auctionId     String\n  bidderAddress String    @db.Citext\n  amountWei     Decimal   @db.Decimal(65, 0)\n  currencyId    String?\n  txHash        String\n  logIndex      Int       @default(0)\n  blockNumber   Int\n  timestamp     DateTime\n  createdAt     DateTime  @default(now())\n  auction       Auction   @relation(fields: [auctionId], references: [id], onDelete: Cascade)\n  currency      Currency? @relation(fields: [currencyId], references: [id])\n\n  @@unique([txHash, logIndex])\n  @@index([auctionId, timestamp])\n  @@index([bidderAddress])\n  @@index([blockNumber])\n}\n\nmodel DeployedContract {\n  id                 String         @id @default(cuid())\n  contractType       ContractType\n  cloneAddress       String         @unique @db.Citext\n  implementationAddr String         @db.Citext\n  factoryAddress     String         @db.Citext\n  deployerAddress    String         @db.Citext\n  txHash             String         @unique\n  blockNumber        Int\n  metadataOption     MetadataOption\n  feeRecipient       String         @db.Citext\n  feeAmountEtnWei    Decimal        @db.Decimal(65, 0)\n  royaltyRecipient   String\n  royaltyBps         Int\n  baseURI            String?\n  maxSupply          Int?\n  rawInit            Json?\n  createdAt          DateTime       @default(now())\n  collectionId       String?        @unique\n  single721Id        String?        @unique\n  single1155Id       String?        @unique\n  collection         Collection?    @relation(fields: [collectionId], references: [id])\n  single1155         Single1155?    @relation(fields: [single1155Id], references: [id])\n  single721          Single721?     @relation(fields: [single721Id], references: [id])\n\n  @@index([factoryAddress])\n  @@index([deployerAddress])\n}\n\nmodel FeeConfig {\n  id              String         @id @default(cuid())\n  contractType    ContractType\n  metadataOption  MetadataOption\n  feeRecipient    String         @db.Citext\n  feeAmountEtnWei Decimal        @db.Decimal(65, 0)\n  active          Boolean        @default(true)\n  createdAt       DateTime       @default(now())\n  updatedAt       DateTime       @updatedAt\n  updatedByUserId String?\n  targetUsdCents  Int?\n  pricingSource   String         @default(\"CRYPTOCOMPARE\")\n  pricingPair     String         @default(\"ETNUSD\")\n  lastPriceUsd    Decimal?       @db.Decimal(20, 10)\n  lastPriceAt     DateTime?\n  logs            FeeConfigLog[]\n\n  @@unique([contractType, metadataOption])\n  @@index([active])\n}\n\nmodel FeeConfigLog {\n  id                   String    @id @default(cuid())\n  feeConfigId          String\n  previousRecipient    String?   @db.Citext\n  newRecipient         String?   @db.Citext\n  previousAmountEtnWei Decimal?  @db.Decimal(65, 0)\n  newAmountEtnWei      Decimal?  @db.Decimal(65, 0)\n  changedByUserId      String?\n  reason               String?\n  createdAt            DateTime  @default(now())\n  feeConfig            FeeConfig @relation(fields: [feeConfigId], references: [id])\n\n  @@index([feeConfigId])\n  @@index([createdAt])\n}\n\nmodel PublicSale {\n  id           String     @id @default(cuid())\n  collectionId String     @unique\n  startTime    DateTime\n  priceEtnWei  Decimal    @db.Decimal(65, 0)\n  maxPerWallet Int\n  maxPerTx     Int\n  createdAt    DateTime   @default(now())\n  updatedAt    DateTime   @default(now())\n  collection   Collection @relation(fields: [collectionId], references: [id])\n}\n\nmodel Presale {\n  id              String                    @id @default(cuid())\n  collectionId    String                    @unique\n  startTime       DateTime\n  endTime         DateTime\n  priceEtnWei     Decimal                   @db.Decimal(65, 0)\n  maxSupply       Int\n  merkleRoot      String\n  whitelistCount  Int?\n  allowlistCommit String?\n  createdAt       DateTime                  @default(now())\n  updatedAt       DateTime                  @updatedAt\n  collection      Collection                @relation(fields: [collectionId], references: [id])\n  whitelist       PresaleWhitelistAddress[]\n}\n\nmodel PresaleWhitelistAddress {\n  id            String  @id @default(cuid())\n  presaleId     String\n  address       String  @db.Citext\n  maxAllocation Int?\n  presale       Presale @relation(fields: [presaleId], references: [id])\n\n  @@unique([presaleId, address])\n  @@index([address])\n  @@index([presaleId])\n}\n\nmodel PresaleDraft {\n  id                  String      @id @default(cuid())\n  creatorUserId       String\n  addresses           Json\n  count               Int\n  merkleRoot          String\n  sha256Commit        String      @unique\n  status              DraftStatus @default(DRAFT)\n  consumedAt          DateTime?\n  consumedByPresaleId String?\n  createdAt           DateTime    @default(now())\n  expiresAt           DateTime?\n\n  @@index([creatorUserId])\n  @@index([status, createdAt])\n}\n\nmodel AssetUpload {\n  id             String      @id @default(cuid())\n  uploaderUserId String?\n  collectionId   String?\n  single721Id    String?\n  single1155Id   String?\n  provider       String      @default(\"PINATA\")\n  cid            String\n  url            String?\n  bytes          Int?\n  sha256         String?\n  contentType    String?\n  originalName   String?\n  createdAt      DateTime    @default(now())\n  collection     Collection? @relation(fields: [collectionId], references: [id])\n  single1155     Single1155? @relation(fields: [single1155Id], references: [id])\n  single721      Single721?  @relation(fields: [single721Id], references: [id])\n\n  @@index([cid])\n  @@index([collectionId])\n  @@index([single721Id])\n  @@index([single1155Id])\n}\n\nmodel CollectionSubmission {\n  id                String           @id @default(cuid())\n  submittedByUserId String\n  contract          String           @unique @db.Citext\n  ownerAddress      String?          @db.Citext\n  name              String?\n  symbol            String?\n  logoUrl           String?\n  coverUrl          String?\n  baseUri           String?\n  supply            Int?\n  description       String?\n  website           String?\n  x                 String?\n  instagram         String?\n  telegram          String?\n  feeTxHash         String?          @unique\n  feePaidWei        Decimal?         @db.Decimal(65, 0)\n  feeVerifiedAt     DateTime?\n  ownershipVerified Boolean          @default(false)\n  status            SubmissionStatus @default(PENDING)\n  statusReason      String?\n  reviewedByUserId  String?\n  reviewedAt        DateTime?\n  createdAt         DateTime         @default(now())\n  updatedAt         DateTime         @updatedAt\n  submittedBy       User             @relation(fields: [submittedByUserId], references: [id])\n\n  @@index([status, createdAt])\n}\n\nmodel NFTRarity {\n  contract  String   @db.Citext\n  tokenId   String\n  score     Decimal  @db.Decimal(38, 18)\n  rank      Int\n  updatedAt DateTime @default(now())\n\n  @@id([contract, tokenId])\n  @@index([contract, rank])\n}\n\nmodel HolderReward {\n  user_id            String   @id\n  wallet_address     String?  @unique @db.Citext\n  last_acc_per_token Decimal  @default(0) @db.Decimal(78, 27)\n  claimed_etn        Decimal  @default(0) @db.Decimal(78, 18)\n  updated_at         DateTime @default(now()) @db.Timestamptz(6)\n}\n\nmodel RewardAccumulator {\n  id            String   @id\n  acc_per_token Decimal  @default(0) @db.Decimal(78, 27)\n  updated_at    DateTime @default(now()) @db.Timestamptz(6)\n}\n\nmodel Currency {\n  id                 String                  @id @default(cuid())\n  symbol             String\n  decimals           Int                     @default(18)\n  kind               CurrencyKind            @default(NATIVE)\n  tokenAddress       String?                 @unique @db.Citext\n  active             Boolean                 @default(true)\n  createdAt          DateTime                @default(now())\n  updatedAt          DateTime                @updatedAt\n  auctions           Auction[]\n  bids               AuctionBid[]\n  holderRewards      HolderRewardMulti[]\n  listings           MarketplaceListing[]\n  sales              MarketplaceSale[]\n  rewardAccumulators RewardAccumulatorMulti?\n  claimLogs          RewardClaimLog[]\n  distributionLogs   RewardDistributionLog[]\n\n  @@unique([symbol, tokenAddress])\n}\n\nmodel MarketplaceSale {\n  id                      String    @id @default(cuid())\n  nftId                   String\n  buyerAddress            String    @db.Citext\n  sellerAddress           String    @db.Citext\n  quantity                Int       @default(1)\n  priceEtnWei             Decimal   @db.Decimal(65, 0)\n  royaltyPaidWei          Decimal?  @db.Decimal(65, 0)\n  marketplaceFeePaidWei   Decimal?  @db.Decimal(65, 0)\n  currencyId              String?\n  priceTokenAmount        Decimal?  @db.Decimal(65, 0)\n  royaltyPaidTokenAmount  Decimal?  @db.Decimal(65, 0)\n  feePaidTokenAmount      Decimal?  @db.Decimal(65, 0)\n  royaltyRecipient        String?   @db.Citext\n  marketplaceFeeRecipient String?   @db.Citext\n  txHash                  String\n  logIndex                Int       @default(0)\n  blockNumber             Int\n  timestamp               DateTime\n  createdAt               DateTime  @default(now())\n  currency                Currency? @relation(fields: [currencyId], references: [id])\n  nft                     NFT       @relation(fields: [nftId], references: [id])\n\n  @@unique([txHash, logIndex])\n  @@index([buyerAddress])\n  @@index([sellerAddress])\n  @@index([nftId])\n  @@index([timestamp])\n  @@index([currencyId, timestamp])\n}\n\nmodel RewardAccumulatorMulti {\n  id          String   @id @default(cuid())\n  currencyId  String   @unique\n  accPerToken Decimal  @default(0) @db.Decimal(78, 27)\n  updatedAt   DateTime @default(now()) @db.Timestamptz(6)\n  currency    Currency @relation(fields: [currencyId], references: [id])\n}\n\nmodel HolderRewardMulti {\n  id              String   @id @default(cuid())\n  userId          String?\n  walletAddress   String   @db.Citext\n  currencyId      String\n  lastAccPerToken Decimal  @default(0) @db.Decimal(78, 27)\n  claimedAmount   Decimal  @default(0) @db.Decimal(78, 18)\n  updatedAt       DateTime @default(now()) @db.Timestamptz(6)\n  currency        Currency @relation(fields: [currencyId], references: [id])\n  user            User?    @relation(fields: [userId], references: [id])\n\n  @@unique([walletAddress, currencyId])\n  @@index([userId])\n}\n\nmodel RewardDistributionLog {\n  id          String   @id @default(cuid())\n  currencyId  String\n  amount      Decimal  @db.Decimal(78, 18)\n  txHash      String?\n  blockNumber Int?\n  timestamp   DateTime @default(now())\n  note        String?\n  currency    Currency @relation(fields: [currencyId], references: [id])\n\n  @@index([currencyId, timestamp])\n}\n\nmodel RewardClaimLog {\n  id            String   @id @default(cuid())\n  walletAddress String   @db.Citext\n  userId        String?\n  currencyId    String\n  amount        Decimal  @db.Decimal(78, 18)\n  txHash        String?\n  timestamp     DateTime @default(now())\n  currency      Currency @relation(fields: [currencyId], references: [id])\n  user          User?    @relation(fields: [userId], references: [id])\n\n  @@index([walletAddress, currencyId, timestamp])\n}\n\nmodel StolenItem {\n  id              String       @id @default(cuid())\n  contract        String       @db.Citext\n  tokenId         String\n  status          StolenStatus @default(FLAGGED)\n  source          StolenSource @default(USER)\n  reporterAddress String?      @db.Citext\n  reporterUserId  String?\n  evidenceUrl     String?\n  notes           String?\n  disputed        Boolean      @default(false)\n  createdAt       DateTime     @default(now())\n  updatedAt       DateTime     @updatedAt\n  reporter        User?        @relation(\"StolenReporter\", fields: [reporterUserId], references: [id])\n\n  @@unique([contract, tokenId])\n  @@index([status])\n  @@index([contract, tokenId, status])\n}\n\nmodel StolenEvent {\n  id           String   @id @default(cuid())\n  contract     String   @db.Citext\n  tokenId      String\n  action       String\n  actorAddress String?  @db.Citext\n  txHash       String?\n  logIndex     Int?     @default(0)\n  blockNumber  Int?\n  timestamp    DateTime @default(now())\n  notes        String?\n  createdAt    DateTime @default(now())\n\n  @@index([contract, tokenId, timestamp])\n  @@index([txHash, logIndex])\n}\n\nmodel MultisigSafe {\n  id             String          @id @default(cuid())\n  contract       String          @unique @db.Citext\n  name           String?\n  threshold      Int\n  createdAt      DateTime        @default(now())\n  updatedAt      DateTime        @updatedAt\n  owners         MultisigOwner[]\n  txs            MultisigTx[]\n  adminProposals AdminProposal[]\n\n  @@index([threshold])\n}\n\nmodel MultisigOwner {\n  id           String       @id @default(cuid())\n  safeId       String\n  ownerAddress String       @db.Citext\n  addedAt      DateTime     @default(now())\n  removedAt    DateTime?\n  safe         MultisigSafe @relation(fields: [safeId], references: [id])\n\n  @@unique([safeId, ownerAddress])\n  @@index([ownerAddress])\n}\n\nmodel MultisigTx {\n  id                   String             @id @default(cuid())\n  safeId               String\n  nonce                Int\n  to                   String             @db.Citext\n  valueWei             Decimal            @default(0) @db.Decimal(65, 0)\n  dataHex              String?\n  operation            Int?\n  submittedBy          String?            @db.Citext\n  status               MultisigTxStatus   @default(SUBMITTED)\n  executedTxHash       String?\n  createdAt            DateTime           @default(now())\n  executedAt           DateTime?\n  approvals            MultisigApproval[]\n  safe                 MultisigSafe       @relation(fields: [safeId], references: [id])\n  linkedAdminProposals AdminProposal[]    @relation(\"AdminProposalSubmittedMultisigTx\")\n\n  @@unique([safeId, nonce])\n  @@index([status])\n  @@index([to])\n}\n\nmodel MultisigApproval {\n  id           String     @id @default(cuid())\n  txId         String\n  ownerAddress String     @db.Citext\n  signature    String?\n  createdAt    DateTime   @default(now())\n  tx           MultisigTx @relation(fields: [txId], references: [id])\n\n  @@unique([txId, ownerAddress])\n  @@index([ownerAddress])\n}\n\nmodel PendingChainAction {\n  id        String                 @id @default(cuid())\n  type      PendingChainActionType\n  txHash    String                 @unique\n  from      String                 @db.Citext\n  chainId   Int\n  payload   Json\n  relatedId String?\n  status    PendingStatus          @default(PENDING)\n  createdAt DateTime               @default(now())\n  updatedAt DateTime               @updatedAt\n\n  @@index([status, createdAt])\n  @@index([type, createdAt])\n}\n\n//\n// Warpool domain models\n//\n\nmodel WarpoolContract {\n  id        String              @id @default(cuid())\n  kind      WarpoolContractKind\n  address   String              @unique @db.Citext\n  chainId   Int\n  label     String?\n  active    Boolean             @default(true)\n  createdAt DateTime            @default(now())\n  updatedAt DateTime            @updatedAt\n\n  @@unique([chainId, kind], map: \"uq_warpool_contract_chain_kind\")\n  @@index([active, kind])\n}\n\nmodel WarpoolQueueConfig {\n  id                   String           @id @default(cuid())\n  chainId              Int\n  queueKey             String           @db.Citext\n  slug                 WarpoolQueueSlug\n  tier                 Int\n  mode                 Int\n  enabled              Boolean\n  singleEntryPerWallet Boolean          @default(true)\n  targetSize           Int\n  minStartSize         Int\n  openDurationSeconds  Int\n  stakeAmountRaw       Decimal          @db.Decimal(78, 0)\n  platformFeeBps       Int\n  firstPlaceBps        Int\n  secondPlaceBps       Int\n  thirdPlaceBps        Int\n  configVersion        BigInt\n  sourceContract       String           @db.Citext\n  syncedAt             DateTime         @default(now())\n  createdAt            DateTime         @default(now())\n  updatedAt            DateTime         @updatedAt\n\n  @@unique([chainId, queueKey, configVersion], map: \"uq_warpool_queue_version\")\n  @@unique([chainId, slug, configVersion], map: \"uq_warpool_slug_version\")\n  @@index([chainId, slug, syncedAt])\n}\n\nmodel WarpoolGlobalConfigSnapshot {\n  id                     String   @id @default(cuid())\n  chainId                Int\n  configContract         String   @db.Citext\n  configVersion          BigInt\n  comradesCollection     String?  @db.Citext\n  relicsCollection       String?  @db.Citext\n  dcntToken              String?  @db.Citext\n  treasury               String?  @db.Citext\n  workerOperator         String?  @db.Citext\n  entriesPaused          Boolean  @default(false)\n  reservationsPaused     Boolean  @default(false)\n  settlementsPaused      Boolean  @default(false)\n  relicsEnabled          Boolean  @default(true)\n  fatigueEnabled         Boolean  @default(true)\n  token11FeeShareEnabled Boolean  @default(true)\n  token11FeeShareBps     Int      @default(0)\n  relicMinDiscountBps    Int?\n  relicMaxDiscountBps    Int?\n  discountSeatCap        Int?\n  token11SeatCap         Int?\n  reservationTtlSeconds  Int?\n  fatigueMaxConsecutive  Int?\n  fatigueCooldownSeconds Int?\n  roundsPerMatch         Int?\n  traitPowerMin          Int?\n  traitPowerMax          Int?\n  roundVarianceMax       Int?\n  microMomentumMax       Int?\n  syncedAt               DateTime @default(now())\n  createdAt              DateTime @default(now())\n\n  @@unique([chainId, configContract, configVersion], map: \"uq_warpool_global_config_version\")\n  @@index([chainId, syncedAt])\n}\n\nmodel WarpoolPool {\n  id                    String               @id @default(cuid())\n  chainId               Int\n  coreContract          String               @db.Citext\n  poolIdOnChain         BigInt\n  queueKey              String               @db.Citext\n  queueSlug             WarpoolQueueSlug?\n  configVersion         BigInt\n  state                 WarpoolPoolStatus\n  tier                  Int\n  mode                  Int\n  singleEntryPerWallet  Boolean\n  targetSize            Int\n  minStartSize          Int\n  entrantCount          Int                  @default(0)\n  runnableSize          Int                  @default(0)\n  stakeAmountRaw        Decimal              @db.Decimal(78, 0)\n  platformFeeBps        Int\n  firstPlaceBps         Int\n  secondPlaceBps        Int\n  thirdPlaceBps         Int\n  relicMinDiscountBps   Int?\n  relicMaxDiscountBps   Int?\n  discountSeatCap       Int                  @default(0)\n  token11SeatCap        Int                  @default(0)\n  token11FeeShareBps    Int                  @default(0)\n  discountSeatsUsed     Int                  @default(0)\n  discountSeatsReserved Int                  @default(0)\n  token11SeatsUsed      Int                  @default(0)\n  comradesCollection    String               @db.Citext\n  relicsCollection      String?              @db.Citext\n  dcntToken             String               @db.Citext\n  treasury              String               @db.Citext\n  openedAt              DateTime\n  expiresAt             DateTime\n  lockedAt              DateTime?\n  battleReadyAt         DateTime?\n  settledAt             DateTime?\n  closedAt              DateTime?\n  expiredRefundedAt     DateTime?\n  seedBlockNumber       Int?\n  openTxHash            String?\n  lockTxHash            String?\n  settleTxHash          String?\n  entries               WarpoolEntry[]\n  reservations          WarpoolReservation[]\n  activities            WarpoolActivity[]\n  battle                WarpoolBattle?\n  createdAt             DateTime             @default(now())\n  updatedAt             DateTime             @updatedAt\n\n  @@unique([chainId, coreContract, poolIdOnChain], map: \"uq_warpool_pool_chain\")\n  @@index([queueKey, state])\n  @@index([queueSlug, state, expiresAt])\n  @@index([state, expiresAt])\n}\n\nmodel WarpoolEntry {\n  id                     String              @id @default(cuid())\n  chainId                Int\n  coreContract           String              @db.Citext\n  entryIdOnChain         BigInt\n  poolId                 String\n  pool                   WarpoolPool         @relation(fields: [poolId], references: [id], onDelete: Cascade)\n  userId                 String?\n  user                   User?               @relation(fields: [userId], references: [id])\n  userAddress            String              @db.Citext\n  nftId                  String?\n  nft                    NFT?                @relation(fields: [nftId], references: [id])\n  comradeContract        String              @db.Citext\n  comradeTokenId         String\n  relicContract          String?             @db.Citext\n  relicTokenId           String?\n  relicType              WarpoolRelicType    @default(NONE)\n  status                 WarpoolEntryStatus\n  placement              Int?\n  selectedForBattle      Boolean             @default(false)\n  relicDiscountBps       Int?\n  baseStakeAmountRaw     Decimal             @db.Decimal(78, 0)\n  paidStakeAmountRaw     Decimal             @db.Decimal(78, 0)\n  refundedStakeAmountRaw Decimal?            @db.Decimal(78, 0)\n  prizeAmountRaw         Decimal?            @db.Decimal(78, 0)\n  joinedAt               DateTime\n  joinedTxHash           String?\n  reservationId          String?             @unique\n  reservation            WarpoolReservation? @relation(fields: [reservationId], references: [id])\n  capture                WarpoolCapture?\n  activities             WarpoolActivity[]\n  createdAt              DateTime            @default(now())\n  updatedAt              DateTime            @updatedAt\n\n  @@unique([chainId, coreContract, entryIdOnChain], map: \"uq_warpool_entry_chain\")\n  @@index([poolId, status])\n  @@index([userAddress, joinedAt])\n  @@index([comradeContract, comradeTokenId])\n  @@index([nftId])\n}\n\nmodel WarpoolReservation {\n  id                   String                   @id @default(cuid())\n  chainId              Int\n  coreContract         String                   @db.Citext\n  reservationIdOnChain BigInt\n  poolId               String\n  pool                 WarpoolPool              @relation(fields: [poolId], references: [id], onDelete: Cascade)\n  userId               String?\n  user                 User?                    @relation(fields: [userId], references: [id])\n  userAddress          String                   @db.Citext\n  nftId                String?\n  nft                  NFT?                     @relation(fields: [nftId], references: [id])\n  comradeContract      String                   @db.Citext\n  comradeTokenId       String\n  relicContract        String                   @db.Citext\n  relicTokenId         String\n  status               WarpoolReservationStatus\n  discountBps          Int?\n  createdAtOnChain     DateTime\n  expiresAtOnChain     DateTime\n  consumedAt           DateTime?\n  expiredAt            DateTime?\n  createdTxHash        String?\n  resolvedTxHash       String?\n  entry                WarpoolEntry?\n  activities           WarpoolActivity[]\n  createdAt            DateTime                 @default(now())\n  updatedAt            DateTime                 @updatedAt\n\n  @@unique([chainId, coreContract, reservationIdOnChain], map: \"uq_warpool_reservation_chain\")\n  @@index([poolId, status, expiresAtOnChain])\n  @@index([userAddress, status])\n}\n\nmodel WarpoolBattle {\n  id               String               @id @default(cuid())\n  poolId           String               @unique\n  pool             WarpoolPool          @relation(fields: [poolId], references: [id], onDelete: Cascade)\n  status           WarpoolBattleStatus  @default(PENDING)\n  bracketSeed      String?              @db.Citext\n  firstEntryId     String?\n  secondEntryId    String?\n  thirdEntryId     String?\n  totalStakeRaw    Decimal?             @db.Decimal(78, 0)\n  prizePoolRaw     Decimal?             @db.Decimal(78, 0)\n  platformFeeRaw   Decimal?             @db.Decimal(78, 0)\n  computedAt       DateTime?\n  submittedAt      DateTime?\n  settledAt        DateTime?\n  settlementTxHash String?\n  rawOutcome       Json?\n  matches          WarpoolBattleMatch[]\n  createdAt        DateTime             @default(now())\n  updatedAt        DateTime             @updatedAt\n\n  @@index([status, updatedAt])\n}\n\nmodel WarpoolBattleMatch {\n  id            String        @id @default(cuid())\n  battleId      String\n  battle        WarpoolBattle @relation(fields: [battleId], references: [id], onDelete: Cascade)\n  roundNumber   Int\n  matchNumber   Int\n  slotAEntryId  String?\n  slotBEntryId  String?\n  winnerEntryId String?\n  loserEntryId  String?\n  status        String        @default(\"PENDING\")\n  rawResult     Json?\n  createdAt     DateTime      @default(now())\n  updatedAt     DateTime      @updatedAt\n\n  @@unique([battleId, roundNumber, matchNumber], map: \"uq_warpool_match_round_number\")\n  @@index([battleId, roundNumber])\n}\n\nmodel WarpoolCapture {\n  id                   String               @id @default(cuid())\n  entryId              String               @unique\n  entry                WarpoolEntry         @relation(fields: [entryId], references: [id], onDelete: Cascade)\n  nftId                String?\n  nft                  NFT?                 @relation(fields: [nftId], references: [id])\n  contract             String               @db.Citext\n  tokenId              String\n  originalOwnerId      String?\n  originalOwner        User?                @relation(\"WarpoolCaptureOriginalOwner\", fields: [originalOwnerId], references: [id])\n  originalOwnerAddress String               @db.Citext\n  capturedAt           DateTime\n  status               WarpoolCaptureStatus @default(HELD)\n  relistStatus         WarpoolRelistStatus  @default(NONE)\n  relistListingId      String?\n  relistListing        MarketplaceListing?  @relation(fields: [relistListingId], references: [id])\n  notes                String?\n  createdAt            DateTime             @default(now())\n  updatedAt            DateTime             @updatedAt\n\n  @@unique([contract, tokenId, capturedAt], map: \"uq_warpool_capture_asset_time\")\n  @@index([status, relistStatus])\n  @@index([contract, tokenId])\n}\n\nmodel WarpoolActivity {\n  id            String              @id @default(cuid())\n  chainId       Int\n  coreContract  String              @db.Citext\n  poolId        String?\n  pool          WarpoolPool?        @relation(fields: [poolId], references: [id], onDelete: Cascade)\n  entryId       String?\n  entry         WarpoolEntry?       @relation(fields: [entryId], references: [id], onDelete: SetNull)\n  reservationId String?\n  reservation   WarpoolReservation? @relation(fields: [reservationId], references: [id], onDelete: SetNull)\n  userId        String?\n  user          User?               @relation(fields: [userId], references: [id])\n  userAddress   String?             @db.Citext\n  nftId         String?\n  nft           NFT?                @relation(fields: [nftId], references: [id])\n  type          WarpoolActivityType\n  txHash        String?             @db.Citext\n  logIndex      Int?\n  blockNumber   Int?\n  timestamp     DateTime\n  payload       Json?\n  createdAt     DateTime            @default(now())\n\n  @@unique([txHash, logIndex], map: \"uq_warpool_activity_log\")\n  @@index([poolId, timestamp])\n  @@index([userAddress, timestamp])\n  @@index([type, timestamp])\n}\n\n//\n// Admin proposal models\n//\n\nmodel AdminProposal {\n  id                     String              @id @default(cuid())\n  area                   AdminProposalArea\n  kind                   AdminProposalKind\n  title                  String\n  slug                   String?             @db.Citext\n  summary                String?\n  description            String?\n  safeId                 String?\n  safe                   MultisigSafe?       @relation(fields: [safeId], references: [id])\n  safeContract           String?             @db.Citext\n  chainId                Int?\n  createdByUserId        String?\n  createdByUser          User?               @relation(\"AdminProposalCreatedByUser\", fields: [createdByUserId], references: [id])\n  createdByAddress       String?             @db.Citext\n  lastEditedByUserId     String?\n  lastEditedByUser       User?               @relation(\"AdminProposalLastEditedByUser\", fields: [lastEditedByUserId], references: [id])\n  lastEditedByAddress    String?             @db.Citext\n  basedOnConfigVersion   BigInt?\n  runtimeReferenceId     String?\n  status                 AdminProposalStatus @default(DRAFT)\n  actionCount            Int                 @default(0)\n  submittedMultisigTxId  String?\n  submittedMultisigTx    MultisigTx?         @relation(\"AdminProposalSubmittedMultisigTx\", fields: [submittedMultisigTxId], references: [id])\n  submittedMultisigNonce Int?\n  submittedAt            DateTime?\n  approvedAt             DateTime?\n  executedAt             DateTime?\n  cancelledAt            DateTime?\n  failedAt               DateTime?\n  snapshotJson           Json?\n  metadataJson           Json?\n  createdAt              DateTime            @default(now())\n  updatedAt              DateTime            @updatedAt\n\n  actions AdminProposalAction[]\n  events  AdminProposalEvent[]\n\n  @@index([area, kind, status, createdAt])\n  @@index([safeContract, status, createdAt])\n  @@index([createdByAddress, createdAt])\n  @@index([submittedMultisigNonce])\n}\n\nmodel AdminProposalAction {\n  id           String                    @id @default(cuid())\n  proposalId   String\n  proposal     AdminProposal             @relation(fields: [proposalId], references: [id], onDelete: Cascade)\n  orderIndex   Int\n  label        String?\n  summary      String?\n  target       String                    @db.Citext\n  valueWei     Decimal                   @default(0) @db.Decimal(78, 0)\n  tokenAddress String?                   @db.Citext\n  dataHex      String\n  functionName String?\n  argsJson     Json?\n  status       AdminProposalActionStatus @default(PENDING)\n  submittedAt  DateTime?\n  executedAt   DateTime?\n  failedAt     DateTime?\n  createdAt    DateTime                  @default(now())\n  updatedAt    DateTime                  @updatedAt\n\n  @@unique([proposalId, orderIndex], map: \"uq_admin_proposal_action_order\")\n  @@index([proposalId, status, orderIndex])\n}\n\nmodel AdminProposalEvent {\n  id           String        @id @default(cuid())\n  proposalId   String\n  proposal     AdminProposal @relation(fields: [proposalId], references: [id], onDelete: Cascade)\n  actorUserId  String?\n  actorUser    User?         @relation(\"AdminProposalEventActorUser\", fields: [actorUserId], references: [id])\n  actorAddress String?       @db.Citext\n  type         String\n  note         String?\n  payloadJson  Json?\n  createdAt    DateTime      @default(now())\n\n  @@index([proposalId, createdAt])\n  @@index([actorAddress, createdAt])\n}\n\nenum ContractType {\n  ERC721_DROP\n  ERC721_SINGLE\n  ERC1155_SINGLE\n}\n\nenum MetadataOption {\n  UPLOAD\n  EXTERNAL\n}\n\nenum ListingStatus {\n  ACTIVE\n  SOLD\n  CANCELLED\n  EXPIRED\n}\n\nenum AuctionStatus {\n  ACTIVE\n  ENDED\n  CANCELLED\n}\n\nenum DraftStatus {\n  DRAFT\n  FINALIZED\n  CONSUMED\n}\n\nenum IndexStatus {\n  PENDING\n  QUEUED\n  INDEXING\n  COMPLETED\n  ERROR\n}\n\nenum NftStatus {\n  PENDING\n  SUCCESS\n  ERROR\n}\n\nenum SubmissionStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\nenum GatewayPref {\n  PUBLIC\n  PINATA\n}\n\nenum MultisigTxStatus {\n  SUBMITTED\n  APPROVED\n  EXECUTED\n  FAILED\n  CANCELLED\n  EXPIRED\n}\n\nenum StolenStatus {\n  FLAGGED\n  CLEARED\n}\n\nenum StolenSource {\n  USER\n  ADMIN\n  PARTNER\n  LAW_ENFORCEMENT\n  MARKETPLACE\n}\n\nenum CurrencyKind {\n  NATIVE\n  ERC20\n}\n\nenum PendingChainActionType {\n  NFT_AUCTION_CREATE\n  NFT_AUCTION_BID\n  NFT_AUCTION_CANCEL\n  NFT_AUCTION_FINALIZE\n\n  WARPOOL_RESERVATION_EXPIRE\n  WARPOOL_POOL_PROCESS_EXPIRED\n  WARPOOL_POOL_MARK_BATTLE_READY\n  WARPOOL_POOL_SETTLE\n  WARPOOL_CAPTURE_RELIST\n}\n\nenum PendingStatus {\n  PENDING\n  CONFIRMED\n  FAILED\n  EXPIRED\n}\n\nenum WarpoolContractKind {\n  CONFIG\n  CORE\n  LENS\n}\n\nenum WarpoolQueueSlug {\n  FORGE_SAFEGUARD\n  LEGION_SAFEGUARD\n  LEGION_VAULTBOUND\n  CROWN_VAULTBOUND\n}\n\nenum WarpoolPoolStatus {\n  OPEN\n  LOCKED\n  BATTLE_READY\n  SETTLING\n  SETTLED\n  CLOSED\n  EXPIRED_REFUNDED\n}\n\nenum WarpoolEntryStatus {\n  JOINED\n  REFUNDED\n  SELECTED\n  SETTLED\n  CAPTURED\n  RETURNED\n}\n\nenum WarpoolReservationStatus {\n  ACTIVE\n  CONSUMED\n  EXPIRED\n  CANCELLED\n}\n\nenum WarpoolRelicType {\n  NONE\n  DISCOUNT\n  GOD\n}\n\nenum WarpoolActivityType {\n  POOL_OPENED\n  POOL_LOCKED\n  POOL_BATTLE_READY\n  POOL_SETTLED\n  POOL_REOPENED\n  POOL_EXPIRED_REFUNDED\n  RESERVATION_CREATED\n  RESERVATION_CONSUMED\n  RESERVATION_EXPIRED\n  ENTRY_JOINED\n  ENTRY_SELECTED\n  ENTRY_REFUNDED\n  ENTRY_CAPTURED\n  ENTRY_RETURNED\n  PRIZE_PAID\n  RELIC_RETURNED\n}\n\nenum WarpoolCaptureStatus {\n  HELD\n  QUEUED_FOR_RELIST\n  RELISTED\n  RELEASED\n}\n\nenum WarpoolRelistStatus {\n  NONE\n  QUEUED\n  LISTED\n  SOLD\n  CANCELLED\n  FAILED\n}\n\nenum WarpoolBattleStatus {\n  PENDING\n  COMPUTED\n  SUBMITTED\n  SETTLED\n  FAILED\n}\n\nenum AdminProposalArea {\n  WARPOOL\n}\n\nenum AdminProposalKind {\n  CONFIG\n  RECOVERY\n}\n\nenum AdminProposalStatus {\n  DRAFT\n  READY\n  SUBMITTED\n  APPROVED\n  EXECUTED\n  CANCELLED\n  FAILED\n}\n\nenum AdminProposalActionStatus {\n  PENDING\n  SUBMITTED\n  EXECUTED\n  FAILED\n}\n"
}

